static boolean nextPermutation(int[] a) {
    int i = a.length - 2;
    while (i >= 0 && a[i] >= a[i + 1]) i--;
    if (i < 0) return false;
    int j = a.length - 1;
    while (a[j] <= a[i]) j--;
    int t = a[i]; a[i] = a[j]; a[j] = t;
    for (int lo = i + 1, hi = a.length - 1; lo < hi; lo++, hi--) {
        t = a[lo]; a[lo] = a[hi]; a[hi] = t;
    }
    return true;
}

