bool nextPermutation(vector<int>& a) {
    int i = (int)a.size() - 2;
    while (i >= 0 && a[i] >= a[i + 1]) i--;
    if (i < 0) return false;
    int j = (int)a.size() - 1;
    while (a[j] <= a[i]) j--;
    swap(a[i], a[j]);
    reverse(a.begin() + i + 1, a.end());
    return true;
}

