static bool nextPermutation(int* a, int n) {
    int i = n - 2;
    while (i >= 0 && a[i] >= a[i + 1]) i--;
    if (i < 0) return false;
    int j = n - 1;
    while (a[j] <= a[i]) j--;
    int t = a[i]; a[i] = a[j]; a[j] = t;
    for (int lo = i + 1, hi = n - 1; lo < hi; lo++, hi--) {
        t = a[lo]; a[lo] = a[hi]; a[hi] = t;
    }
    return true;
}

static int cmp_int(const void* x, const void* y) {
    int p = *(const int*)x, q = *(const int*)y;
    return (p > q) - (p < q);
}

// Calls visit(a, n) for every distinct arrangement, in order; returns how many.
int allArrangements(int* a, int n, void (*visit)(const int*, int)) {
    qsort(a, n, sizeof(int), cmp_int);
    int count = 0;
    do {
        if (visit) visit(a, n);
        count++;
    } while (nextPermutation(a, n));
    return count;
}

