static int[] kthPermutation(int n, long k) {
    long[] fact = new long[n + 1];
    fact[0] = 1;
    for (int i = 1; i <= n; i++) fact[i] = fact[i - 1] * i;
    List<Integer> left = new ArrayList<>();
    for (int v = 1; v <= n; v++) left.add(v);
    k--;
    int[] out = new int[n];
    for (int slots = n; slots >= 1; slots--) {
        long block = fact[slots - 1];
        out[n - slots] = left.remove((int) (k / block));
        k %= block;
    }
    return out;
}

