vector<int> kthPermutation(int n, long long k) {
    vector<long long> fact(n + 1, 1);
    for (int i = 1; i <= n; i++) fact[i] = fact[i - 1] * i;
    vector<int> left(n);
    iota(left.begin(), left.end(), 1);
    k--;
    vector<int> out;
    for (int slots = n; slots >= 1; slots--) {
        long long block = fact[slots - 1];
        auto it = left.begin() + k / block;
        out.push_back(*it);
        left.erase(it);
        k %= block;
    }
    return out;
}

