void kthPermutation(int n, long long k, int* out) {
    long long fact[21] = {1};
    for (int i = 1; i <= n; i++) fact[i] = fact[i - 1] * i;
    int left[20];
    for (int v = 0; v < n; v++) left[v] = v + 1;
    k--;
    for (int slots = n; slots >= 1; slots--) {
        long long block = fact[slots - 1];
        int idx = (int)(k / block);
        out[n - slots] = left[idx];
        for (int t = idx; t < slots - 1; t++) left[t] = left[t + 1];
        k %= block;
    }
}
